+static ftenum_t
+get_function_ftype(stnode_t *st_node)
+{
+	df_func_def_t *funcdef;
+	GSList        *params;
+	unsigned       nparams;
+
+	funcdef  = sttype_function_funcdef(st_node);
+	params   = sttype_function_params(st_node);
+	nparams  = g_slist_length(params);
+
+	if (nparams < 1)
+		return FT_NONE;
+	return funcdef->return_type(params);
